#include <stdio.h>

void divmod(int a, int b, int *q, int *r) {
    *q = a / b;
    *r = a % b;
}

int main(void) {
    int a, b;
    int q, r;
    if (scanf("%d %d", &a, &b) != 2 || b <= 0) return 1;
    divmod(a, b, &q, &r);
    printf("q=%d r=%d\n", q, r);
    return 0;
}
